    g=G[k]; c=Counter(x for r in g for x in r)
    mn=[x for x in c if x!=c.most_common(1)[0][0]][0]
    cs=comps(g,mn)
    print(k,'minority=',mn,'sizes:',sorted(cs,reverse=True)[:6],'ncomps:',len(cs),'total:',sum(cs))

