import os,re,json
from collections import Counter, deque
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        seg=t[m.end():].split('\n')[:h]
        if k not in G and all(len(r.split())==w and all(x.isdigit() for x in r.split()) for r in seg):
            G[k]=[[int(x) for x in r.split()] for r in seg]
    return G
G=load()
def comps(di,val):
    h=len(di); w=len(di[0]); seen=[[False]*w for _ in range(h)]; out=[]
    offs=[(-1,0),(1,0),(0,-1),(0,1)]
    for y in range(h):
        for x in range(w):
            if di[y][x]==val and not seen[y][x]:
                st=[(y,x)]; seen[y][x]=True; n=0; cells=[]
                while st:
                    yy,xx=st.pop(); cells.append((yy,xx)); n+=1
                    for dy,dx in offs:
                        a,b=yy+dy,xx+dx
                        if 0<=a<h and 0<=b<w and not seen[a][b] and di[a][b]==val:
                            seen[a][b]=True; st.append((a,b))
                out.append((n,cells))
    return out
