    di=G[key]; c=Counter(x for r_ in di for x in r_)
    bg=c.most_common(1)[0][0]; mi=[v for v in c if v!=bg][0]
    bcs=comps(di,bg); mcs=comps(di,mi)
    bg_enclosed=[n for n,_ in bcs if any(y not in (0,len(di)-1) for y,x in _) and False]  # placeholder
    bg_touch=sum(1 for n,_ in bcs if any(x in(0,len(di[0])-1) or y in(0,len(di)-1) for y,x in _))
    enclosed_bg=[n for n,_ in bcs if not any(y in(0,len(di)-1) or x in(0,len(di[0])-1) for y,x in _)]
    mtouch=sum(1 for n,_ in mcs if any(y in(0,len(di)-1) or x in(0,len(di[0])-1) for y,x in _))
    print(i,'bg4comps',len(bcs),'enclosed bg(4conn)',enclosed_bg,'minrtouch',mtouch,'mincomp8',len(comps(di,mi)))

