for i in [1,2,3,4,5,6,7,'T']:
    key='Demo pair %d input'%i if i!='T' else 'Test input'
    di=G[key]; c=Counter(x for r_ in di for x in r_)
    bg=c.most_common(1)[0][0]; mi=[v for v in c if v!=bg][0]
    h=len(di); w=len(di[0])
    onb=sum(1 for y in range(h) for x in range(w) if (y in(0,h-1) or x in(0,w-1)) and di[y][x]!=bg)
    enc=[]
    def touches_border(cells): return any(y in(0,h-1) or x in(0,w-1) for y,x in cells)
    for val in (bg,mi):
        cs=comps(di,val)
        if val==bg:
            for n,_ in cs: enc.append(('bg',n,touches_border(_)))
        else:
            for n,_ in cs: enc.append(('m ',n,touches_border(_)))
    print(i,'min_on_border_cells',onb,'minority_comps_touching',sum(1 for e in enc if e[0]=='m ' and e[2]),['E' if not e[2] else '.' for e in enc if e[0]=='bg'])

for i in [1,2,3,4,5,6,7,'T']:
    key='Demo pair %d input'%i if i!='T' else 'Test input'
    di=G[key]; c=Counter(x for r_ in di for x in r_)
    bg=c.most_common(1)[0][0]; mi=[v for v in c if v!=bg][0]
    h=len(di); w=len(di[0])
    def maxrun(dimension):
        runs=[]
        if dimension=='h':
            for y in range(h):
                row=di[y]; L=1; prev=row[0]
                for x in range(1,w):
                    if row[x]==prev: L+=1
                    else: runs.append(L); L=1; prev=row[x]
                runs.append(L)
        elif dimension=='v':
            for x in range(w):
                col=[di[y][x] for y in range(h)]; L=1; prev=col[0]
                for y in range(1,h):
                    if col[y]==prev: L+=1
                    else: runs.append(L); L=1; prev=col[y]
                runs.append(L)
        return max(runs) if runs else 0
    print(i,'min_run_h',maxrun('h'),'min_run_v',maxrun('v'))
